#include <stdio.h>
#include <string.h>

enum LineStatus { LINE_END, LINE_OK, LINE_LONG, LINE_BAD, LINE_IO };

/* Read one full record. capacity includes a slot for '\0'. */
static enum LineStatus read_line(char text[], size_t capacity)
{
    size_t used = 0;
    int overflow = 0;
    int contains_nul = 0;
    int byte = getchar();

    if (byte == EOF) {
        return ferror(stdin) ? LINE_IO : LINE_END;
    }

    while (byte != '\n' && byte != EOF) {
        int next = getchar();
        if (!(byte == '\r' && next == '\n')) {
            if (byte == 0) {
                contains_nul = 1;
            }
            if (used + 1 < capacity) {
                ((unsigned char *)text)[used++] = (unsigned char)byte;
            } else {
                overflow = 1;
            }
        }
        byte = next;
    }
    text[used] = '\0';
    if (ferror(stdin)) {
        return LINE_IO;
    }
    if (contains_nul) {
        return LINE_BAD;
    }
    return overflow ? LINE_LONG : LINE_OK;
}

int main(void)
{
    char text[9];
    if (read_line(text, sizeof text) != LINE_OK) {
        puts("invalid");
        return 0;
    }
    /* TODO: compare whole keys. */
    if (strncmp(text, "OK", 2) == 0 || strncmp(text, "ADJ", 3) == 0) {
        printf("known %zu\n", strlen(text));
    } else {
        puts("unknown");
    }
    return 0;
}

